const express = require('express');
const sqlite3 = require('sqlite3').verbose();
const bcrypt = require('bcrypt');
const jwt = require('jsonwebtoken');
const dotenv = require('dotenv');
const { z } = require('zod');

dotenv.config();

const app = express();
app.use(express.json());

const PORT = process.env.PORT || 5000;
const JWT_SECRET = process.env.JWT_SECRET || 'fallback_secret';
const JWT_EXPIRES_IN = process.env.JWT_EXPIRES_IN || '15m';
const REFRESH_TOKEN_SECRET = process.env.REFRESH_TOKEN_SECRET || 'fallback_refresh_secret';
const REFRESH_TOKEN_EXPIRES_IN = process.env.REFRESH_TOKEN_EXPIRES_IN || '7d';
const DB_PATH = process.env.DB_PATH || './tasks.db';

// Initialize database
const db = new sqlite3.Database(DB_PATH, (err) => {
  if (err) {
    console.error('Error opening database:', err.message);
  } else {
    console.log('Connected to SQLite database.');
    initializeDatabase();
  }
});

// Database initialization
function initializeDatabase() {
  db.serialize(() => {
    // Users table
    db.run(`
      CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        username TEXT UNIQUE NOT NULL,
        email TEXT UNIQUE NOT NULL,
        password_hash TEXT NOT NULL,
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP
      )
    `);

    // Tasks table
    db.run(`
      CREATE TABLE IF NOT EXISTS tasks (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        title TEXT NOT NULL,
        description TEXT,
        priority TEXT DEFAULT 'low',
        status TEXT DEFAULT 'todo',
        due_date DATETIME,
        tags TEXT, -- JSON stringified array
        user_id INTEGER NOT NULL,
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
        updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
        FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
      )
    `);

    // Indexes for better query performance
    db.run(`CREATE INDEX IF NOT EXISTS idx_tasks_user_id ON tasks(user_id)`);
    db.run(`CREATE INDEX IF NOT EXISTS idx_tasks_status ON tasks(status)`);
    db.run(`CREATE INDEX IF NOT EXISTS idx_tasks_priority ON tasks(priority)`);
  });
}

// Zod schemas for validation
const userRegisterSchema = z.object({
  username: z.string().min(3, 'Username must be at least 3 characters'),
  email: z.string().email('Invalid email address'),
  password: z.string().min(6, 'Password must be at least 6 characters')
});

const userLoginSchema = z.object({
  email: z.string().email('Invalid email address'),
  password: z.string().min(1, 'Password is required')
});

const taskSchema = z.object({
  title: z.string().min(1, 'Title is required'),
  description: z.string().optional(),
  priority: z.enum(['low', 'medium', 'high']).default('low'),
  status: z.enum(['todo', 'in_progress', 'done']).default('todo'),
  due_date: z.string().datetime().optional().nullable(),
  tags: z.array(z.string()).default([])
});

// Helper function to generate JWT
function generateAccessToken(user) {
  return jwt.sign(
    { userId: user.id, username: user.username },
    JWT_SECRET,
    { expiresIn: JWT_EXPIRES_IN }
  );
}

// Helper function to generate refresh token
function generateRefreshToken(user) {
  return jwt.sign(
    { userId: user.id },
    REFRESH_TOKEN_SECRET,
    { expiresIn: REFRESH_TOKEN_EXPIRES_IN }
  );
}

// Middleware to authenticate JWT
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, JWT_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
}

// Registration endpoint
app.post('/api/register', async (req, res) => {
  try {
    const validatedData = userRegisterSchema.parse(req.body);
    const { username, email, password } = validatedData;

    // Check if user already exists
    db.get(
      `SELECT id FROM users WHERE username = ? OR email = ?`,
      [username, email],
      (err, row) => {
        if (err) {
          return res.status(500).json({ error: 'Database error' });
        }
        if (row) {
          return res.status(409).json({ error: 'Username or email already exists' });
        }

        // Hash password
        bcrypt.hash(password, 10, (err, hash) => {
          if (err) {
            return res.status(500).json({ error: 'Error hashing password' });
          }

          // Insert user
          db.run(
            `INSERT INTO users (username, email, password_hash) VALUES (?, ?, ?)`,
            [username, email, hash],
            function (err) {
              if (err) {
                return res.status(500).json({ error: 'Error creating user' });
              }
              const userId = this.lastID;
              const user = { id: userId, username, email };
              const accessToken = generateAccessToken(user);
              const refreshToken = generateRefreshToken(user);

              res.status(201).json({
                message: 'User registered successfully',
                user: { id: userId, username, email },
                accessToken,
                refreshToken
              });
            }
          );
        });
      }
    );
  } catch (error) {
    if (error instanceof z.ZodError) {
      return res.status(400).json({ error: 'Validation failed', details: error.errors });
    }
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Login endpoint
app.post('/api/login', async (req, res) => {
  try {
    const validatedData = userLoginSchema.parse(req.body);
    const { email, password } = validatedData;

    db.get(
      `SELECT id, username, email, password_hash FROM users WHERE email = ?`,
      [email],
      (err, user) => {
        if (err) {
          return res.status(500).json({ error: 'Database error' });
        }
        if (!user) {
          return res.status(401).json({ error: 'Invalid credentials' });
        }

        bcrypt.compare(password, user.password_hash, (err, isMatch) => {
          if (err) {
            return res.status(500).json({ error: 'Error comparing passwords' });
          }
          if (!isMatch) {
            return res.status(401).json({ error: 'Invalid credentials' });
          }

          const userPayload = { id: user.id, username: user.username, email: user.email };
          const accessToken = generateAccessToken(userPayload);
          const refreshToken = generateRefreshToken(userPayload);

          res.json({
            message: 'Login successful',
            user: userPayload,
            accessToken,
            refreshToken
          });
        });
      }
    );
  } catch (error) {
    if (error instanceof z.ZodError) {
      return res.status(400).json({ error: 'Validation failed', details: error.errors });
    }
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Refresh token endpoint
app.post('/api/refresh-token', (req, res) => {
  const { refreshToken } = req.body;
  if (!refreshToken) {
    return res.status(400).json({ error: 'Refresh token required' });
  }

  jwt.verify(refreshToken, REFRESH_TOKEN_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid or expired refresh token' });
    }

    // Get user from database
    db.get(
      `SELECT id, username, email FROM users WHERE id = ?`,
      [user.userId],
      (err, userData) => {
        if (err) {
          return res.status(500).json({ error: 'Database error' });
        }
        if (!userData) {
          return res.status(404).json({ error: 'User not found' });
        }

        const userPayload = { id: userData.id, username: userData.username, email: userData.email };
        const accessToken = generateAccessToken(userPayload);
        const newRefreshToken = generateRefreshToken(userPayload);

        res.json({
          accessToken,
          refreshToken: newRefreshToken
        });
      }
    );
  });
});

// Task endpoints
app.get('/api/tasks', authenticateToken, (req, res) => {
  const userId = req.user.userId;
  let query = `SELECT * FROM tasks WHERE user_id = ?`;
  const params = [userId];

  // Filtering
  const { status, priority, tags, search, sortBy, sortOrder, page, limit } = req.query;

  if (status) {
    query += ` AND status = ?`;
    params.push(status);
  }
  if (priority) {
    query += ` AND priority = ?`;
    params.push(priority);
  }
  if (tags) {
    // Simple tag matching - assumes tags are stored as JSON array string
    // For simplicity, we'll do a basic string match (in production, use proper JSON querying)
    query += ` AND tags LIKE ?`;
    params.push(`%${tags}%`);
  }
  if (search) {
    query += ` AND (title LIKE ? OR description LIKE ?)`;
    params.push(`%${search}%`, `%${search}%`);
  }

  // Sorting
  const validSortFields = ['title', 'priority', 'status', 'created_at', 'due_date'];
  const sortField = validSortFields.includes(sortBy) ? sortBy : 'created_at';
  const sortDirection = sortOrder && sortOrder.toUpperCase() === 'ASC' ? 'ASC' : 'DESC';
  query += ` ORDER BY ${sortField} ${sortDirection}`;

  // Pagination
  const pageNum = parseInt(page) || 1;
  const limitNum = parseInt(limit) || 10;
  const offset = (pageNum - 1) * limitNum;

  query += ` LIMIT ? OFFSET ?`;
  params.push(limitNum, offset);

  db.all(query, params, (err, rows) => {
    if (err) {
      return res.status(500).json({ error: 'Error fetching tasks' });
    }

    // Parse tags JSON strings
    const tasks = rows.map(task => ({
      ...task,
      tags: task.tags ? JSON.parse(task.tags) : []
    }));

    // Get total count for pagination metadata
    const countQuery = `SELECT COUNT(*) as total FROM tasks WHERE user_id = ?`;
    const countParams = [userId];

    // Apply same filters for count query (simplified)
    let countQueryString = countQuery;
    if (status) {
      countQueryString += ` AND status = ?`;
      countParams.push(status);
    }
    if (priority) {
      countQueryString += ` AND priority = ?`;
      countParams.push(priority);
    }
    if (tags) {
      countQueryString += ` AND tags LIKE ?`;
      countParams.push(`%${tags}%`);
    }
    if (search) {
      countQueryString += ` AND (title LIKE ? OR description LIKE ?)`;
      countParams.push(`%${search}%`, `%${search}%`);
    }

    db.get(countQueryString, countParams, (err, countResult) => {
      if (err) {
        return res.status(500).json({ error: 'Error counting tasks' });
      }

      res.json({
        tasks,
        pagination: {
          total: countResult.total,
          page: pageNum,
          limit: limitNum,
          totalPages: Math.ceil(countResult.total / limitNum)
        }
      });
    });
  });
});

app.get('/api/tasks/:id', authenticateToken, (req, res) => {
  const userId = req.user.userId;
  const taskId = req.params.id;

  db.get(
    `SELECT * FROM tasks WHERE id = ? AND user_id = ?`,
    [taskId, userId],
    (err, task) => {
      if (err) {
        return res.status(500).json({ error: 'Error fetching task' });
      }
      if (!task) {
        return res.status(404).json({ error: 'Task not found' });
      }

      res.json({
        ...task,
        tags: task.tags ? JSON.parse(task.tags) : []
      });
    }
  );
});

app.post('/api/tasks', authenticateToken, (req, res) => {
  try {
    const validatedData = taskSchema.parse(req.body);
    const userId = req.user.userId;
    const { title, description, priority, status, due_date, tags } = validatedData;

    db.run(
      `INSERT INTO tasks (title, description, priority, status, due_date, tags, user_id) 
       VALUES (?, ?, ?, ?, ?, ?, ?)`,
      [
        title,
        description || null,
        priority,
        status,
        due_date || null,
        JSON.stringify(tags),
        userId
      ],
      function (err) {
        if (err) {
          return res.status(500).json({ error: 'Error creating task' });
        }
        const taskId = this.lastID;

        db.get(
          `SELECT * FROM tasks WHERE id = ?`,
          [taskId],
          (err, task) => {
            if (err) {
              return res.status(500).json({ error: 'Error fetching created task' });
            }
            res.status(201).json({
              ...task,
              tags: task.tags ? JSON.parse(task.tags) : []
            });
          }
        );
      }
    );
  } catch (error) {
    if (error instanceof z.ZodError) {
      return res.status(400).json({ error: 'Validation failed', details: error.errors });
    }
    res.status(500).json({ error: 'Internal server error' });
  }
});

app.put('/api/tasks/:id', authenticateToken, (req, res) => {
  try {
    const validatedData = taskSchema.partial().parse(req.body);
    const userId = req.user.userId;
    const taskId = req.params.id;

    // Check if task exists and belongs to user
    db.get(
      `SELECT * FROM tasks WHERE id = ? AND user_id = ?`,
      [taskId, userId],
      (err, task) => {
        if (err) {
          return res.status(500).json({ error: 'Error fetching task' });
        }
        if (!task) {
          return res.status(404).json({ error: 'Task not found' });
        }

        const updateFields = [];
        const values = [];

        Object.keys(validatedData).forEach(key => {
          if (key === 'tags') {
            updateFields.push(`${key} = ?`);
            values.push(JSON.stringify(validatedData[key]));
          } else {
            updateFields.push(`${key} = ?`);
            values.push(validatedData[key]);
          }
        });

        if (updateFields.length === 0) {
          return res.status(400).json({ error: 'No fields to update' });
        }

        // Add updated_at timestamp
        updateFields.push('updated_at = ?');
        values.push(new Date().toISOString());

        values.push(taskId);
        values.push(userId);

        const query = `UPDATE tasks SET ${updateFields.join(', ')} WHERE id = ? AND user_id = ?`;

        db.run(query, values, function (err) {
          if (err) {
            return res.status(500).json({ error: 'Error updating task' });
          }

          if (this.changes === 0) {
            return res.status(404).json({ error: 'Task not found' });
          }

          db.get(
            `SELECT * FROM tasks WHERE id = ?`,
            [taskId],
            (err, updatedTask) => {
              if (err) {
                return res.status(500).json({ error: 'Error fetching updated task' });
              }
              res.json({
                ...updatedTask,
                tags: updatedTask.tags ? JSON.parse(updatedTask.tags) : []
              });
            }
          );
        });
      }
    );
  } catch (error) {
    if (error instanceof z.ZodError) {
      return res.status(400).json({ error: 'Validation failed', details: error.errors });
    }
    res.status(500).json({ error: 'Internal server error' });
  }
});

app.delete('/api/tasks/:id', authenticateToken, (req, res) => {
  const userId = req.user.userId;
  const taskId = req.params.id;

  db.run(
    `DELETE FROM tasks WHERE id = ? AND user_id = ?`,
    [taskId, userId],
    function (err) {
      if (err) {
        return res.status(500).json({ error: 'Error deleting task' });
      }
      if (this.changes === 0) {
        return res.status(404).json({ error: 'Task not found' });
      }
      res.json({ message: 'Task deleted successfully' });
    }
  );
});

// Health check endpoint
app.get('/api/health', (req, res) => {
  res.json({ status: 'OK', timestamp: new Date().toISOString() });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).json({ error: 'Something went wrong!' });
});

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

