const request = require('supertest');
const { app, db } = require('../index'); // Access the app and db instance

// Wait for database to be ready before running tests
beforeAll((done) => {
  // If database is already ready, proceed immediately
  if (db.constructor.name === 'Database') {
    // Database is already initialized
    done();
  } else {
    // Wait for database initialization (this shouldn't happen with our current setup)
    setTimeout(done, 1000);
  }
});

// Clean up before each test
beforeEach((done) => {
  db.serialize(() => {
    db.run('DELETE FROM tasks', () => {
      db.run('DELETE FROM users', done);
    });
  });
});

afterAll((done) => {
  db.close(done);
});

describe('Authentication Endpoints', () => {
  describe('POST /api/register', () => {
    it('should register a new user successfully', async () => {
      const response = await request(app)
        .post('/api/register')
        .send({
          username: 'testuser',
          email: 'test@example.com',
          password: 'password123'
        })
        .expect(201);

      expect(response.body).toHaveProperty('message', 'User registered successfully');
      expect(response.body.user).toHaveProperty('username', 'testuser');
      expect(response.body.user).toHaveProperty('email', 'test@example.com');
      expect(response.body).toHaveProperty('accessToken');
      expect(response.body).toHaveProperty('refreshToken');
    });

    it('should return 400 for validation errors', async () => {
      const response = await request(app)
        .post('/api/register')
        .send({
          username: 'ab', // too short
          email: 'invalid-email',
          password: '123' // too short
        })
        .expect(400);

      expect(response.body).toHaveProperty('error', 'Validation failed');
    });

    it('should return 409 for duplicate username/email', async () => {
      // Create first user
      await request(app)
        .post('/api/register')
        .send({
          username: 'testuser',
          email: 'test@example.com',
          password: 'password123'
        });

      // Try to register with same username
      const response = await request(app)
        .post('/api/register')
        .send({
          username: 'testuser',
          email: 'different@example.com',
          password: 'password123'
        })
        .expect(409);

      expect(response.body).toHaveProperty('error', 'Username or email already exists');
    });
  });

  describe('POST /api/login', () => {
    beforeEach(async () => {
      // Create a test user
      await request(app)
        .post('/api/register')
        .send({
          username: 'testuser',
          email: 'test@example.com',
          password: 'password123'
        });
    });

    it('should login user with valid credentials', async () => {
      const response = await request(app)
        .post('/api/login')
        .send({
          email: 'test@example.com',
          password: 'password123'
        })
        .expect(200);

      expect(response.body).toHaveProperty('message', 'Login successful');
      expect(response.body.user).toHaveProperty('username', 'testuser');
      expect(response.body).toHaveProperty('accessToken');
      expect(response.body).toHaveProperty('refreshToken');
    });

    it('should return 401 for invalid credentials', async () => {
      const response = await request(app)
        .post('/api/login')
        .send({
          email: 'test@example.com',
          password: 'wrongpassword'
        })
        .expect(401);

      expect(response.body).toHaveProperty('error', 'Invalid credentials');
    });

    it('should return 400 for validation errors', async () => {
      const response = await request(app)
        .post('/api/login')
        .send({
          email: 'invalid-email',
          password: ''
        })
        .expect(400);

      expect(response.body).toHaveProperty('error', 'Validation failed');
    });
  });

  describe('POST /api/refresh-token', () => {
    let accessToken;
    let refreshToken;

    beforeEach(async () => {
      // Register and login to get tokens
      const registerResponse = await request(app)
        .post('/api/register')
        .send({
          username: 'testuser',
          email: 'test@example.com',
          password: 'password123'
        });

      accessToken = registerResponse.body.accessToken;
      refreshToken = registerResponse.body.refreshToken;
    });

    it('should refresh access token with valid refresh token', async () => {
      const response = await request(app)
        .post('/api/refresh-token')
        .send({ refreshToken })
        .expect(200);

      expect(response.body).toHaveProperty('accessToken');
      expect(response.body).toHaveProperty('refreshToken');

      // New tokens should be different from old ones
      expect(response.body.accessToken).not.toEqual(accessToken);
    });

    it('should return 403 for invalid refresh token', async () => {
      const response = await request(app)
        .post('/api/refresh-token')
        .send({ refreshToken: 'invalid-token' })
        .expect(403);

      expect(response.body).toHaveProperty('error', 'Invalid or expired refresh token');
    });
  });
});

const request = require('supertest');
const { app, db } = require('../index');

// Wait for database to be ready before running tests
beforeAll((done) => {
  // If database is already ready, proceed immediately
  if (db.constructor.name === 'Database') {
    // Database is already initialized
    done();
  } else {
    // Wait for database initialization (this shouldn't happen with our current setup)
    setTimeout(done, 1000);
  }
});

describe('Task Endpoints', () => {
  let accessToken;
  let userId;

  // Create a test user and get auth token before each test
  beforeEach(async () => {
    // Clean up database
    await new Promise((resolve, reject) => {
      db.serialize(() => {
        db.run('DELETE FROM tasks', (err) => {
          if (err) return reject(err);
          db.run('DELETE FROM users', (err) => {
            if (err) return reject(err);
            resolve();
          });
        });
      });
    });

    // Register a test user
    const registerResponse = await request(app)
      .post('/api/register')
      .send({
        username: 'testuser',
        email: 'test@example.com',
        password: 'password123'
      });

    // Login to get token
    const loginResponse = await request(app)
      .post('/api/login')
      .send({
        email: 'test@example.com',
        password: 'password123'
      });

    accessToken = loginResponse.body.accessToken;
    userId = loginResponse.body.user.id;
  });

  afterAll((done) => {
    db.close(done);
  });

  describe('GET /api/tasks', () => {
    it('should return empty array for new user', async () => {
      const response = await request(app)
        .get('/api/tasks')
        .set('Authorization', `Bearer ${accessToken}`)
        .expect(200);

      expect(Array.isArray(response.body.tasks)).toBe(true);
      expect(response.body.tasks.length).toBe(0);
      expect(response.body.pagination).toHaveProperty('total', 0);
    });

    it('should return paginated tasks with filters', async () => {
      // Create test tasks
      await request(app)
        .post('/api/tasks')
        .set('Authorization', `Bearer ${accessToken}`)
        .send({
          title: 'Test Task 1',
          description: 'First test task',
          priority: 'high',
          status: 'todo',
          tags: ['work', 'urgent']
        });

      await request(app)
        .post('/api/tasks')
        .set('Authorization', `Bearer ${accessToken}`)
        .send({
          title: 'Test Task 2',
          description: 'Second test task',
          priority: 'low',
          status: 'done',
          tags: ['personal']
        });

      // Test basic fetch
      let response = await request(app)
        .get('/api/tasks')
        .set('Authorization', `Bearer ${accessToken}`)
        .expect(200);

      expect(response.body.tasks.length).toBe(2);
      expect(response.body.pagination.total).toBe(2);

      // Test filtering by status
      response = await request(app)
        .get('/api/tasks?status=todo')
        .set('Authorization', `Bearer ${accessToken}`)
        .expect(200);

      expect(response.body.tasks.length).toBe(1);
      expect(response.body.tasks[0].status).toBe('todo');

      // Test filtering by priority
      response = await request(app)
        .get('/api/tasks?priority=low')
        .set('Authorization', `Bearer ${accessToken}`)
        .expect(200);

      expect(response.body.tasks.length).toBe(1);
      expect(response.body.tasks[0].priority).toBe('low');

      // Test filtering by tags
      response = await request(app)
        .get('/api/tasks?tags=work')
        .set('Authorization', `Bearer ${accessToken}`)
        .expect(200);

      expect(response.body.tasks.length).toBe(1);
      expect(response.body.tasks[0].tags).toContain('work');

      // Test search
      response = await request(app)
        .get('/api/tasks?search=First')
        .set('Authorization', `Bearer ${accessToken}`)
        .expect(200);

      expect(response.body.tasks.length).toBe(1);
      expect(response.body.tasks[0].title).toBe('Test Task 1');

      // Test sorting
      response = await request(app)
        .get('/api/tasks?sortBy=title&sortOrder=asc')
        .set('Authorization', `Bearer ${accessToken}`)
        .expect(200);

      expect(response.body.tasks[0].title).toBe('Test Task 1');

      // Test pagination
      response = await request(app)
        .get('/api/tasks?limit=1&page=1')
        .set('Authorization', `Bearer ${accessToken}`)
        .expect(200);

      expect(response.body.tasks.length).toBe(1);
      expect(response.body.pagination.total).toBe(2);
      expect(response.body.pagination.page).toBe(1);
      expect(response.body.pagination.limit).toBe(1);
      expect(response.body.pagination.totalPages).toBe(2);
    });
  });

  describe('GET /api/tasks/:id', () => {
    it('should return a specific task', async () => {
      // Create a task
      const createResponse = await request(app)
        .post('/api/tasks')
        .set('Authorization', `Bearer ${accessToken}`)
        .send({
          title: 'Specific Task',
          description: 'Task details',
          priority: 'medium',
          status: 'in_progress',
          due_date: '2026-12-31',
          tags: ['test']
        });

      const taskId = createResponse.body.id;

      // Fetch the task
      const response = await request(app)
        .get(`/api/tasks/${taskId}`)
        .set('Authorization', `Bearer ${accessToken}`)
        .expect(200);

      expect(response.body).toHaveProperty('id', taskId);
      expect(response.body.title).toBe('Specific Task');
      expect(response.body.description).toBe('Task details');
      expect(response.body.priority).toBe('medium');
      expect(response.body.status).toBe('in_progress');
      expect(response.body.due_date).toBe('2026-12-31T00:00:00.000Z');
      expect(response.body.tags).toContain('test');
    });

    it('should return 404 for non-existent task', async () => {
      const response = await request(app)
        .get('/api/tasks/99999')
        .set('Authorization', `Bearer ${accessToken}`)
        .expect(404);

      expect(response.body).toHaveProperty('error', 'Task not found');
    });

    it('should return 401 without token', async () => {
      await request(app)
        .get('/api/tasks/1')
        .expect(401);
    });
  });

  describe('POST /api/tasks', () => {
    it('should create a new task', async () => {
      const taskData = {
        title: 'New Task',
        description: 'Task description',
        priority: 'high',
        status: 'todo',
        due_date: '2026-06-30',
        tags: ['important', 'project']
      };

      const response = await request(app)
        .post('/api/tasks')
        .set('Authorization', `Bearer ${accessToken}`)
        .send(taskData)
        .expect(201);

      expect(response.body).toHaveProperty('id');
      expect(response.body.title).toBe(taskData.title);
      expect(response.body.description).toBe(taskData.description);
      expect(response.body.priority).toBe(taskData.priority);
      expect(response.body.status).toBe(taskData.status);
      expect(new Date(response.body.due_date).toISOString()).toBe(new Date(taskData.due_date).toISOString());
      expect(response.body.tags).toEqual(expect.arrayContaining(taskData.tags));
    });

    it('should return 400 for validation errors', async () => {
      const response = await request(app)
        .post('/api/tasks')
        .set('Authorization', `Bearer ${accessToken}`)
        .send({
          title: '', // empty title
          priority: 'invalid', // invalid priority
          status: 'invalid_status' // invalid status
        })
        .expect(400);

      expect(response.body).toHaveProperty('error', 'Validation failed');
    });

    it('should return 401 without token', async () => {
      await request(app)
        .post('/api/tasks')
        .send({ title: 'Test' })
        .expect(401);
    });
  });

  describe('PUT /api/tasks/:id', () => {
    it('should update an existing task', async () => {
      // Create a task
      const createResponse = await request(app)
        .post('/api/tasks')
        .set('Authorization', `Bearer ${accessToken}`)
        .send({
          title: 'Original Title',
          description: 'Original description',
          priority: 'low',
          status: 'todo'
        });

      const taskId = createResponse.body.id;

      // Update the task
      const updateData = {
        title: 'Updated Title',
        description: 'Updated description',
        priority: 'high',
        status: 'done'
      };

      const response = await request(app)
        .put(`/api/tasks/${taskId}`)
        .set('Authorization', `Bearer ${accessToken}`)
        .send(updateData)
        .expect(200);

      expect(response.body.title).toBe(updateData.title);
      expect(response.body.description).toBe(updateData.description);
      expect(response.body.priority).toBe(updateData.priority);
      expect(response.body.status).toBe(updateData.status);
      // Check that updated_at is newer than created_at
      expect(new Date(response.body.updated_at).getTime()).toBeGreaterThan(new Date(response.body.created_at).getTime());
    });

    it('should return 400 for validation errors', async () => {
      // Create a task
      const createResponse = await request(app)
        .post('/api/tasks')
        .set('Authorization', `Bearer ${accessToken}`)
        .send({
          title: 'Test Task',
          priority: 'low',
          status: 'todo'
        });

      const taskId = createResponse.body.id;

      // Try to update with invalid data
      const response = await request(app)
        .put(`/api/tasks/${taskId}`)
        .set('Authorization', `Bearer ${accessToken}`)
        .send({
          priority: 'invalid_priority'
        })
        .expect(400);

      expect(response.body).toHaveProperty('error', 'Validation failed');
    });

    it('should return 404 for non-existent task', async () => {
      const response = await request(app)
        .put('/api/tasks/99999')
        .set('Authorization', `Bearer ${accessToken}`)
        .send({ title: 'Updated' })
        .expect(404);

      expect(response.body).toHaveProperty('error', 'Task not found');
    });

    it('should return 401 without token', async () => {
      await request(app)
        .put('/api/tasks/1')
        .send({ title: 'Test' })
        .expect(401);
    });
  });

  describe('DELETE /api/tasks/:id', () => {
    it('should delete a task', async () => {
      // Create a task
      const createResponse = await request(app)
        .post('/api/tasks')
        .set('Authorization', `Bearer ${accessToken}`)
        .send({
          title: 'Task to Delete',
          priority: 'medium',
          status: 'todo'
        });

      const taskId = createResponse.body.id;

      // Delete the task
      await request(app)
        .delete(`/api/tasks/${taskId}`)
        .set('Authorization', `Bearer ${accessToken}`)
        .expect(200);

      // Verify task is deleted
      await request(app)
        .get(`/api/tasks/${taskId}`)
        .set('Authorization', `Bearer ${accessToken}`)
        .expect(404);
    });

    it('should return 404 for non-existent task', async () => {
      const response = await request(app)
        .delete('/api/tasks/99999')
        .set('Authorization', `Bearer ${accessToken}`)
        .expect(404);

      expect(response.body).toHaveProperty('error', 'Task not found');
    });

    it('should return 401 without token', async () => {
      await request(app)
        .delete('/api/tasks/1')
        .expect(401);
    });
  });
});

