const request = require('supertest');
const { app, db } = require('../index');

describe('Authentication Endpoints', () => {
  beforeEach((done) => {
    db.serialize(() => {
      db.run('DELETE FROM users', () => {
        db.run('DELETE FROM tasks', done);
      });
    });
  });

  afterAll((done) => {
    db.close(done);
  });

  describe('POST /api/register', () => {
    it('should register a new user successfully', async () => {
      const response = await request(app)
        .post('/api/register')
        .send({
          username: 'testuser',
          email: 'test@example.com',
          password: 'password123'
        })
        .expect(201);

      expect(response.body).toHaveProperty('message', 'User registered successfully');
      expect(response.body.user).toHaveProperty('username', 'testuser');
      expect(response.body.user).toHaveProperty('email', 'test@example.com');
      expect(response.body).toHaveProperty('accessToken');
      expect(response.body).toHaveProperty('refreshToken');
    });

    it('should return 400 for validation errors', async () => {
      const response = await request(app)
        .post('/api/register')
        .send({
          username: 'ab',
          email: 'invalid-email',
          password: '123'
        })
        .expect(400);

      expect(response.body).toHaveProperty('error', 'Validation failed');
    });

    it('should return 409 for duplicate username/email', async () => {
      // Create first user
      await request(app)
        .post('/api/register')
        .send({
          username: 'testuser',
          email: 'test@example.com',
          password: 'password123'
        });

      // Try to register with same username
      const response = await request(app)
        .post('/api/register')
        .send({
          username: 'testuser',
          email: 'different@example.com',
          password: 'password123'
        })
        .expect(409);

      expect(response.body).toHaveProperty('error', 'Username or email already exists');
    });
  });

  describe('POST /api/login', () => {
    beforeEach(async () => {
      await request(app)
        .post('/api/register')
        .send({
          username: 'testuser',
          email: 'test@example.com',
          password: 'password123'
        });
    });

    it('should login user with valid credentials', async () => {
      const response = await request(app)
        .post('/api/login')
        .send({
          email: 'test@example.com',
          password: 'password123'
        })
        .expect(200);

      expect(response.body).toHaveProperty('message', 'Login successful');
      expect(response.body.user).toHaveProperty('username', 'testuser');
      expect(response.body).toHaveProperty('accessToken');
      expect(response.body).toHaveProperty('refreshToken');
    });

    it('should return 401 for invalid credentials', async () => {
      const response = await request(app)
        .post('/api/login')
        .send({
          email: 'test@example.com',
          password: 'wrongpassword'
        })
        .expect(401);

      expect(response.body).toHaveProperty('error', 'Invalid credentials');
    });

    it('should return 400 for validation errors', async () => {
      const response = await request(app)
        .post('/api/login')
        .send({
          email: 'invalid-email',
          password: ''
        })
        .expect(400);

      expect(response.body).toHaveProperty('error', 'Validation failed');
    });
  });

  describe('POST /api/refresh-token', () => {
    let refreshToken;

    beforeEach(async () => {
      const registerResponse = await request(app)
        .post('/api/register')
        .send({
          username: 'testuser',
          email: 'test@example.com',
          password: 'password123'
        });

      refreshToken = registerResponse.body.refreshToken;
    });

    it('should refresh access token with valid refresh token', async () => {
      const response = await request(app)
        .post('/api/refresh-token')
        .send({ refreshToken })
        .expect(200);

      expect(response.body).toHaveProperty('accessToken');
      expect(response.body).toHaveProperty('refreshToken');
    });

    it('should return 403 for invalid refresh token', async () => {
      const response = await request(app)
        .post('/api/refresh-token')
        .send({ refreshToken: 'invalid-token' })
        .expect(403);

      expect(response.body).toHaveProperty('error', 'Invalid or expired refresh token');
    });
  });
});

