app.get('/api/tasks', authenticateToken, (req, res) => {
  const userId = req.user.id;
  let query = `SELECT * FROM tasks WHERE user_id = ?`;
  const params = [userId];

  // Filtering
  const { status, priority, tags, search, sortBy, sortOrder, page, limit } = req.query;

  if (status) {
    query += ` AND status = ?`;
    params.push(status);
  }
  if (priority) {
    query += ` AND priority = ?`;
    params.push(priority);
  }
  if (tags) {
    // For tag filtering, we need to check if the tags JSON array contains the tag
    // Since SQLite doesn't have great JSON support, we'll do a simple check
    // This is a simplified approach - in production you'd want to normalize tags
    query += ` AND tags LIKE ?`;
    params.push(`%\"${tags}\"%`);
  }
  if (search) {
    query += ` AND (title LIKE ? OR description LIKE ?)`;
    params.push(`%${search}%`, `%${search}%`);
  }

  // Sorting
  const validSortFields = ['title', 'priority', 'status', 'created_at', 'due_date'];
  const sortField = validSortFields.includes(sortBy) ? sortBy : 'created_at';
  const sortDirection = sortOrder && sortOrder.toUpperCase() === 'ASC' ? 'ASC' : 'DESC';
  query += ` ORDER BY ${sortField} ${sortDirection}`;

  // Pagination
  const pageNum = parseInt(page) || 1;
  const limitNum = parseInt(limit) || 10;
  const offset = (pageNum - 1) * limitNum;

  query += ` LIMIT ? OFFSET ?`;
  params.push(limitNum, offset);

  db.all(query, params, (err, rows) => {
    if (err) {
      return res.status(500).json({ error: 'Error fetching tasks' });
    }

    // Parse tags JSON strings
    const tasks = rows.map(task => ({
      ...task,
      tags: task.tags ? JSON.parse(task.tags) : []
    }));

    // Get total count for pagination metadata
    const countQuery = `SELECT COUNT(*) as total FROM tasks WHERE user_id = ?`;
    const countParams = [userId];

    // Apply same filters for count query (simplified)
    let countQueryString = countQuery;
    if (status) {
      countQueryString += ` AND status = ?`;
      countParams.push(status);
    }
    if (priority) {
      countQueryString += ` AND priority = ?`;
      countParams.push(priority);
    }
    if (tags) {
      countQueryString += ` AND tags LIKE ?`;
      countParams.push(`%${tags}%`);
    }
    if (search) {
      countQueryString += ` AND (title LIKE ? OR description LIKE ?)`;
      countParams.push(`%${search}%`, `%${search}%`);
    }

    db.get(countQueryString, countParams, (err, countResult) => {
      if (err) {
        return res.status(500).json({ error: 'Error counting tasks' });
      }

      res.json({
        tasks,
        pagination: {
          total: countResult.total,
          page: pageNum,
          limit: limitNum,
          totalPages: Math.ceil(countResult.total / limitNum)
        }
      });
    });
  });
});

